#include <stdio.h>
#include <SilikoCore/SilikoCore.h>


int main(int argc, char *argv[])
{
    // Make sure there is an argument to process:
    if (argc != 2)
    {
        fprintf(stderr, "usage: %s <expression>\n", argv[0]);
        return 1;
    }

    // Setup the engine
    SilikoEngine *engine = SilikoEngineCreate();
    SilikoInstallOperations(engine);
    SilikoInstallMathFunctions(engine);

    // Code to use the Siliko Core library
    SilikoInput *source = SilikoStringInputCreate(argv[1]);

    // Cleanup
    SilikoEngineDestroy(engine);
}

// Code to use the Siliko Core library
SilikoInput *source = SilikoStringInputCreate(argv[1]);
SilikoNode *tree = SilikoParseInfix(source);

// Code to use the Siliko Core library
SilikoInput *source = SilikoStringInputCreate(argv[1]);
SilikoNode *tree = SilikoParseInfix(source);   
SilikoValue *result = SilikoEvaluate(engine, tree);

// Print the result
switch (SilikoValueGetStatus(result))
{
case (SilikoValueInteger):
    printf("> %lli\n", SilikoValueGetInteger(result));
    break;
case (SilikoValueReal):
    printf("> %f\n", SilikoValueGetReal(result));
    break;
case (SilikoValueError):
    switch (SilikoValueGetError(result))
    {
    case(SilikoErrorNone):
        // This shouldn't be a result, but we check here
        // just in case.
        puts("Unexpected error");
        break;
    case(SilikoErrorNullObject):
        puts("Out of memory");
        break;
    case SilikoErrorSyntax:
        puts("Syntax error");
        break;
    case SilikoErrorZeroDivision:
        puts("Division by zero");
        break;
    case SilikoErrorFunctionName:
        puts("Function not found");
        break;
    case SilikoErrorFunctionArguments:
        puts("Bad argument count");
        break;
    case SilikoErrorDomain:
        puts("Domain error");
        break;
    case SilikoErrorRange:
        puts("Range error");
        break;
    }
    break;
}

#include <stdio.h>
#include <SilikoCore/SilikoCore.h>


int main(int argc, char *argv[])
{
    // Make sure there is an argument to process:
    if (argc != 2)
    {
        fprintf(stderr, "usage: %s <expression>", argv[0]);
        return 1;
    }

    // Setup the engine
    SilikoEngine *engine = SilikoEngineCreate();
    SilikoInstallOperations(engine);
    SilikoInstallMathFunctions(engine);

    // Code to use the Siliko Core library
    SilikoInput *source = SilikoStringInputCreate(argv[1]);
    SilikoNode *tree = SilikoParseInfix(source);   
    SilikoValue *result = SilikoEvaluate(engine, tree);

    // Print the result
    switch (SilikoValueGetStatus(result))
    {
    case (SilikoValueInteger):
        printf("> %lli\n", SilikoValueGetInteger(result));
        break;
    case (SilikoValueReal):
        printf("> %f\n", SilikoValueGetReal(result));
        break;
    case (SilikoValueError):
        switch (SilikoValueGetError(result))
        {
        case(SilikoErrorNone):
            // This shouldn't be a result, but we check here
            // just in case.
            puts("Unexpected error");
            break;
        case(SilikoErrorNullObject):
            puts("Out of memory");
            break;
        case SilikoErrorSyntax:
            puts("Syntax error");
            break;
        case SilikoErrorZeroDivision:
            puts("Division by zero");
            break;
        case SilikoErrorFunctionName:
            puts("Function not found");
            break;
        case SilikoErrorFunctionArguments:
            puts("Bad argument count");
            break;
        case SilikoErrorDomain:
            puts("Domain error");
            break;
        case SilikoErrorRange:
            puts("Range error");
            break;
        }
        break;
    }

    // Cleanup
    SilikoValueDestroy(result);
    SilikoNodeDestroy(tree);
    SilikoEngineDestroy(engine);
}
